pub struct ImeEnvelopeBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> ImeEnvelopeBuilder<'a, 'b, A> {
  #[inline]
  pub fn add_protocol_version(&mut self, protocol_version: u16) {
    self.fbb_.push_slot::<u16>(ImeEnvelope::VT_PROTOCOL_VERSION, protocol_version, 1);
  }
  #[inline]
  pub fn add_sequence(&mut self, sequence: u64) {
    self.fbb_.push_slot::<u64>(ImeEnvelope::VT_SEQUENCE, sequence, 0);
  }
  #[inline]
  pub fn add_payload_type(&mut self, payload_type: ImePayload) {
    self.fbb_.push_slot::<ImePayload>(ImeEnvelope::VT_PAYLOAD_TYPE, payload_type, ImePayload::NONE);
  }
  #[inline]
  pub fn add_payload(&mut self, payload: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(ImeEnvelope::VT_PAYLOAD, payload);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> ImeEnvelopeBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    ImeEnvelopeBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<ImeEnvelope<'a>> {
    let o = self.fbb_.end_table(self.start_);
    flatbuffers::WIPOffset::new(o.value())
  }
}

